import React from "react";
import styled from "styled-components";

const FooterContainer = styled.footer`
  background-color: #f0f0f0;
  padding: 40px 20px;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  border-top: 1px solid #ddd;
`;

const Column = styled.div`
  flex: 1;
  min-width: 200px;
  margin: 10px 20px;

  h4 {
    font-size: 18px;
    margin-bottom: 16px;
    color: #333;
  }

  ul {
    list-style: none;
    padding: 0;

    li {
      margin-bottom: 10px;
      font-size: 14px;
      color: #666;

      &:hover {
        color: #000;
        cursor: pointer;
      }
    }
  }
`;

const Copyright = styled.div`
  width: 100%;
  text-align: center;
  margin-top: 30px;
  font-size: 14px;
  color: #999;
`;

const Footer = () => {
  return (
    <FooterContainer>
      <Column>
        <h4>Về chúng tôi</h4>
        <ul>
          <li>Giới thiệu</li>
          <li>Liên hệ</li>
          <li>Blog</li>
        </ul>
      </Column>

      <Column>
        <h4>Hỗ trợ</h4>
        <ul>
          <li>Câu hỏi thường gặp</li>
          <li>Chính sách bảo mật</li>
          <li>Điều khoản dịch vụ</li>
        </ul>
      </Column>

      <Column>
        <h4>Kết nối</h4>
        <ul>
          <li>Facebook</li>
          <li>Twitter</li>
          <li>LinkedIn</li>
        </ul>
      </Column>

      <Copyright>© 2025 YourCompany. All rights reserved.</Copyright>
    </FooterContainer>
  );
};

export default Footer;
